CREATE TEMP TABLE qd_global_universes_to_seed ON COMMIT DROP AS
SELECT id, code
FROM qd_universes u
WHERE u.is_system = TRUE
  AND u.code IN ('sp500', 'nasdaq100', 'dow30', 'sp400', 'sp600', 'russell1000', 'crypto_top100', 'hk_hsi', 'hk_tech30', 'hk_china_enterprises50', 'hk_etf', 'us_etf', 'us_sector_information_technology', 'us_sector_health_care', 'us_sector_financials', 'us_sector_consumer_discretionary', 'us_sector_communication_services', 'us_sector_industrials', 'us_sector_consumer_staples', 'us_sector_energy', 'us_sector_utilities', 'us_sector_real_estate', 'us_sector_materials')
  AND NOT EXISTS (
    SELECT 1 FROM qd_universe_members m WHERE m.universe_id = u.id
  );

